#![cfg(not(any(feature = "cuda-11040",feature = "cuda-11050",feature = "cuda-11060",feature = "cuda-11070",feature = "cuda-11080")))]
use super::tracked_pool_tests::seams;
use crate::driver::{result::context_test_seams,sys,CudaMemPool,DriverError,MemPoolProps,PrimaryContextLifetime,PrimaryContextLossCause};
use std::sync::{Arc,Mutex};
fn props()->MemPoolProps{MemPoolProps{max_size:0,release_threshold:128}}
#[test]
fn cleanup_known_loss_disarms_last_pool_owner_without_native_destroy(){
    let driver=context_test_seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let native=seams::Guard::new();let lifetime=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map_err(|e|e.0 as u32).unwrap();lifetime.record_error(DriverError(sys::CUresult::CUDA_ERROR_CONTEXT_IS_DESTROYED));let before=driver.snapshot();
    drop(pool);assert_eq!(native.snapshot().destroy_attempts,0);let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));drop(lifetime);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
}
#[test]
fn cleanup_healthy_last_owner_holds_admission_through_one_native_destroy(){
    let driver=context_test_seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let native=seams::Guard::new();let lifetime=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map_err(|e|e.0 as u32).unwrap();let phases=Arc::new(Mutex::new(Vec::new()));let log=Arc::clone(&phases);let weak=Arc::downgrade(&lifetime);native.set_hook(move|phase|{let lifetime=weak.upgrade().unwrap();let active=lifetime.state.try_lock().expect("native pool destruction must be unlocked").active_leases;log.lock().unwrap().push((phase,active));});
    drop(pool);native.set_hook(|_|{});assert_eq!(*phases.lock().unwrap(),vec![(4,1)]);assert_eq!((native.snapshot().destroy_attempts,native.snapshot().destroyed),(1,1));assert!(lifetime.loss().is_none());drop(lifetime);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
}
#[test]
fn cleanup_idle_pool_discovers_inactive_primary_before_destroy(){
    let driver=context_test_seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let native=seams::Guard::new();let lifetime=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map_err(|e|e.0 as u32).unwrap();driver.set_primary_active(false);let before=driver.snapshot();
    drop(pool);assert_eq!(native.snapshot().destroy_attempts,0);assert_eq!(lifetime.loss().unwrap().cause,PrimaryContextLossCause::PrimaryInactive);let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries+1,before.id_queries,before.queries,before.binds));drop(lifetime);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
}
#[test]
fn cleanup_actual_destroy_failure_freezes_before_later_native_pool_growth(){
    for error in [sys::CUresult::CUDA_ERROR_OUT_OF_MEMORY,sys::CUresult::CUDA_ERROR_INVALID_CONTEXT,sys::CUresult::CUDA_ERROR_UNKNOWN]{let driver=context_test_seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let native=seams::Guard::new();let lifetime=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map_err(|e|e.0 as u32).unwrap();native.set_destroy_error(Some(error));
        let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||drop(pool)));native.set_destroy_error(None);assert!(result.is_ok());assert_eq!((native.snapshot().destroy_attempts,native.snapshot().destroyed),(1,0));assert_eq!(lifetime.loss().map(|loss|(loss.recorded_id,loss.observed_id,loss.cause)),Some((17,None,PrimaryContextLossCause::DriverStatus(error))));let first=lifetime.loss();let before=driver.snapshot();assert_eq!(CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map(drop).map_err(|e|e.0 as u32),Err(error as u32));assert_eq!(native.snapshot().create_attempts,1);lifetime.record_error(DriverError(sys::CUresult::CUDA_ERROR_CONTEXT_IS_DESTROYED));assert_eq!(lifetime.loss(),first);let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));drop(lifetime);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));}
}
#[test]
fn use_pool_queries_and_trim_hold_unlocked_admission(){
    let driver=context_test_seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let native=seams::Guard::new();let lifetime=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map_err(|e|e.0 as u32).unwrap();let phases=Arc::new(Mutex::new(Vec::new()));let log=Arc::clone(&phases);let weak=Arc::downgrade(&lifetime);native.set_hook(move|phase|{let lifetime=weak.upgrade().unwrap();let active=lifetime.state.try_lock().expect("pool native use must be unlocked").active_leases;log.lock().unwrap().push((phase,active));});
    assert_eq!(pool.reserved_current().map_err(|e|e.0 as u32),Ok(4096));assert_eq!(pool.used_current().map_err(|e|e.0 as u32),Ok(16));assert_eq!(pool.release_threshold().map_err(|e|e.0 as u32),Ok(128));assert_eq!(pool.trim_to(0).map_err(|e|e.0 as u32),Ok(()));native.set_hook(|_|{});assert_eq!(*phases.lock().unwrap(),vec![(2,1),(2,1),(2,1),(3,1)]);assert_eq!(lifetime.state.lock().unwrap().active_leases,0);drop(pool);drop(lifetime);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
}
#[test]
fn use_cached_loss_refuses_every_pool_query_and_trim_without_native_calls(){
    let driver=context_test_seams::Guard::new();let _legacy=super::mem_pool::seams::Reset::new();super::mem_pool::seams::DRIVER_VERSION.set(Some(12060));let native=seams::Guard::new();let lifetime=PrimaryContextLifetime::new(0).map_err(|e|e.0 as u32).unwrap();let pool=CudaMemPool::create_tracked(Arc::clone(&lifetime),&props()).map_err(|e|e.0 as u32).unwrap();let lost=sys::CUresult::CUDA_ERROR_CONTEXT_IS_DESTROYED;lifetime.record_error(DriverError(lost));let before=driver.snapshot();
    for result in [pool.reserved_current(),pool.reserved_high(),pool.used_current(),pool.used_high(),pool.release_threshold()]{assert_eq!(result.map_err(|e|e.0 as u32),Err(lost as u32));}assert_eq!(pool.trim_to(0).map_err(|e|e.0 as u32),Err(lost as u32));assert_eq!((native.snapshot().gets,native.snapshot().trims),(0,0));let after=driver.snapshot();assert_eq!((after.primary_queries,after.id_queries,after.queries,after.binds),(before.primary_queries,before.id_queries,before.queries,before.binds));assert_eq!(pool.max_size(),None);drop(pool);assert_eq!(native.snapshot().destroy_attempts,0);drop(lifetime);assert_eq!((driver.snapshot().retains,driver.snapshot().releases),(1,1));
}
